void sctp_update_association(struct sctp_association *asoc, struct sctp_association *new) {
    /* Copy new parameters from 'new' to 'asoc' */
    asoc->rwnd = new->rwnd;
    asoc->ssthresh = new->ssthresh;
    asoc->cwnd = new->cwnd;
    asoc->mtu = new->mtu;
    asoc->flight_size = new->flight_size;

    /* Remove peer addresses from 'asoc' that are not in 'new' */
    struct sctp_transport *t, *tmp;
    list_for_each_entry_safe(t, tmp, &asoc->peer.transports, transports) {
        int found = 0;
        list_for_each_entry(struct sctp_transport, new_t, &new->peer.transports, transports) {
            if (sctp_cmp_addr(t->ipaddr, new_t->ipaddr)) {
                found = 1;
                break;
            }
        }
        if (!found) {
            list_del(&t->transports);
            kfree(t);
        }
    }

    /* If association is established, handle TSN and reassembly */
    if (asoc->state == SCTP_STATE_ESTABLISHED) {
        asoc->next_tsn = new->next_tsn;
        sctp_ssnmap_clear(&asoc->ssnmap);
        sctp_flush_ulpq(&asoc->ulpq);
        asoc->error_count = 0;
    } else {
        /* Otherwise, add new peer addresses */
        list_for_each_entry(t, &new->peer.transports, transports) {
            struct sctp_transport *new_t = kzalloc(sizeof(*new_t), GFP_KERNEL);
            if (new_t) {
                memcpy(new_t, t, sizeof(*new_t));
                list_add_tail(&new_t->transports, &asoc->peer.transports);
            }
        }

        /* Manage SSN map and association ID */
        sctp_ssnmap_update(&asoc->ssnmap, &new->ssnmap);
        asoc->assoc_id = new->assoc_id;
    }

    /* Update SCTP-AUTH related parameters */
    asoc->authenticator = new->authenticator;
    asoc->a_side = new->a_side;
    asoc->auth_key = new->auth_key;
    asoc->auth_key_id = new->auth_key_id;
    memcpy(asoc->shared_keys, new->shared_keys, sizeof(asoc->shared_keys));
}

void sctp_assoc_update(struct sctp_association *asoc, struct sctp_association *new) {
    struct sctp_transport *t, *tmp;

    /* Copy new parameters from 'new' to 'asoc' */
    asoc->rwnd = new->rwnd;
    asoc->ssthresh = new->ssthresh;
    asoc->cwnd = new->cwnd;
    asoc->mtu = new->mtu;

    /* Remove peer addresses in 'asoc' that are not in 'new' */
    list_for_each_entry_safe(t, tmp, &asoc->peer.transport_addr_list, list) {
        int found = 0;
        list_for_each_entry(tmp, &new->peer.transport_addr_list, list) {
            if (sctp_cmp_addr(t, tmp) == 0) {
                found = 1;
                break;
            }
        }
        if (!found) {
            list_del(&t->list);
            sctp_transport_free(t);
        }
    }

    if (asoc->state >= SCTP_STATE_ESTABLISHED) {
        asoc->next_tsn = new->next_tsn;
        sctp_ssnmap_clear(&asoc->ssnmap);
        sctp_ulpq_flush(&asoc->ulpq);
        asoc->error_count = 0;
    } else {
        list_for_each_entry(t, &new->peer.transport_addr_list, list) {
            struct sctp_transport *newt = sctp_transport_alloc(asoc);
            if (newt) {
                memcpy(&newt->ip, &t->ip, sizeof(t->ip));
                list_add_tail(&newt->list, &asoc->peer.transport_addr_list);
            }
        }

        if (asoc->state == SCTP_STATE_COOKIE_ECHOED) {
            sctp_ssnmap_copy(&asoc->ssnmap, &new->ssnmap);
        }
        asoc->assoc_id = new->assoc_id;
    }

    /* Copy over SCTP-AUTH related parameters */
    asoc->auth_supported = new->auth_supported;
    asoc->auth_num = new->auth_num;
    memcpy(asoc->auth_hmacs, new->auth_hmacs, sizeof(asoc->auth_hmacs));

    if (new->active_key) {
        sctp_key_free(asoc->active_key);
        asoc->active_key = sctp_key_dup(new->active_key);
    }

    if (new->secret_key) {
        sctp_key_free(asoc->secret_key);
        asoc->secret_key = sctp_key_dup(new->secret_key);
    }
}

void sctp_update_association(struct sctp_association *asoc, struct sctp_association *new) {
    /* Copy new parameters from 'new' to 'asoc' */
    asoc->rwnd = new->rwnd;
    asoc->ssthresh = new->ssthresh;
    asoc->cwnd = new->cwnd;
    asoc->partial_failure = new->partial_failure;
    asoc->in_shutdown = new->in_shutdown;

    /* Remove peer addresses from 'asoc' not present in 'new' */
    struct sctp_sockaddr *tmp, *next;
    for (tmp = asoc->peer_addrs; tmp; tmp = next) {
        next = tmp->next;
        int found = 0;

        for (struct sctp_sockaddr *addr = new->peer_addrs; addr; addr = addr->next) {
            if (sctp_compare_sockaddr(tmp->addr, addr->addr)) {
                found = 1;
                break;
            }
        }

        if (!found) {
            sctp_remove_sockaddr(asoc, tmp);
        }
    }

    if (asoc->state == SCTP_ESTABLISHED) {
        asoc->next_tsn = new->next_tsn;
        sctp_clear_ssn_map(asoc);
        sctp_flush_ulp_reassembly(asoc);
        asoc->error_count = 0;
    } else {
        struct sctp_sockaddr *addr;
        for (addr = new->peer_addrs; addr; addr = addr->next) {
            if (!sctp_find_sockaddr(asoc, &addr->addr)) {
                sctp_add_sockaddr(asoc, addr->addr);
            }
        }

        if (asoc->ssn_map) {
            sctp_reset_ssn_map(asoc);
        } else {
            asoc->ssn_map = sctp_init_ssn_map();
        }

        asoc->assoc_id = new->assoc_id;
    }

    /* Update SCTP-AUTH related parameters */
    asoc->auth_key = new->auth_key;
    asoc->auth_key_len = new->auth_key_len;
    asoc->active_keyid = new->active_keyid;
    asoc->num_active_keys = new->num_active_keys;
    memcpy(asoc->active_keys, new->active_keys, sizeof(asoc->active_keys));
}

void sctp_update_association(struct sctp_association *asoc, struct sctp_association *new) {
    /* Copy new parameters from 'new' to 'asoc' */
    asoc->next_tsn = new->next_tsn;
    asoc->ssn_map = new->ssn_map;
    asoc->auth_params = new->auth_params;
    asoc->shared_keys = new->shared_keys;
    asoc->peer_auth_capable = new->peer_auth_capable;

    /* Remove peer addresses from 'asoc' not present in 'new' */
    struct sctp_addr *addr, *temp;
    sctp_list_for_each_entry_safe(addr, temp, &asoc->peer_addrs, list) {
        int found = 0;
        sctp_list_for_each_entry(addr, &new->peer_addrs, list) {
            if (sctp_addr_cmp(&addr->addr, &addr->addr))
                found = 1;
        }
        if (!found) {
            sctp_list_del(&addr->list);
            free(addr);
        }
    }

    if (asoc->state == SCTP_STATE_ESTABLISHED) {
        /* Update next TSN */
        asoc->next_tsn = new->next_tsn;

        /* Clear SSN map */
        memset(asoc->ssn_map, 0, sizeof(asoc->ssn_map));

        /* Flush the ULP reassembly queue */
        sctp_flush_reassembly(asoc);

        /* Reset overall error count */
        asoc->error_count = 0;
    } else {
        /* Add new peer addresses */
        sctp_list_for_each_entry(addr, &new->peer_addrs, list) {
            int found = 0;
            sctp_list_for_each_entry(temp, &asoc->peer_addrs, list) {
                if (sctp_addr_cmp(&addr->addr, &temp->addr))
                    found = 1;
            }
            if (!found) {
                struct sctp_addr *new_addr = malloc(sizeof(struct sctp_addr));
                memcpy(new_addr, addr, sizeof(struct sctp_addr));
                sctp_list_add(&new_addr->list, &asoc->peer_addrs);
            }
        }

        /* Manage SSN map and association ID */
        asoc->ssn_map = new->ssn_map;
        asoc->assoc_id = new->assoc_id;
    }

    /* Update peer parameters for SCTP-AUTH */
    asoc->auth_params = new->auth_params;
    asoc->shared_keys = new->shared_keys;
}
